18	import jakarta.persistence.*;
19	import java.time.LocalDate;
20	import java.util.*;
21	
22	
23	/**
24	 * Simple business object representing a pet.
25	 *
26	 * @author Ken Krebs
27	 * @author Juergen Hoeller
28	 * @author Sam Brannen
29	 */
30	@Entity
31	@Table(name = "pets")
32	public class Pet extends NamedEntity {
33	
34	    @Column(name = "birth_date", columnDefinition = "DATE")
35	    private LocalDate birthDate;
36	
37	    @ManyToOne(cascade = CascadeType.ALL)
38	    @JoinColumn(name = "type_id")
39	    private PetType type;
40	
41	    @ManyToOne
42	    @JoinColumn(name = "owner_id")
43	    private Owner owner;
44	
45	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "pet", fetch = FetchType.EAGER)
46	    private Set<Visit> visits;
47	
48	    public LocalDate getBirthDate() {
49	        return this.birthDate;
50	    }
51	
52	    public void setBirthDate(LocalDate birthDate) {
53	        this.birthDate = birthDate;
54	    }
55	
56	    public PetType getType() {
57	        return this.type;
58	    }
59	
60	    public void setType(PetType type) {
61	        this.type = type;
62	    }
63	
64	    public Owner getOwner() {
65	        return this.owner;
66	    }
67	
68	    public void setOwner(Owner owner) {
69	        this.owner = owner;
70	    }
71	
72	    protected Set<Visit> getVisitsInternal() {
73	        if (this.visits == null) {
74	            this.visits = new HashSet<>();
75	        }
76	        return this.visits;
77	    }
78	
79	    protected void setVisitsInternal(Set<Visit> visits) {
80	        this.visits = visits;
81	    }
82	
83	    public List<Visit> getVisits() {
84	        List<Visit> sortedVisits = new ArrayList<>(getVisitsInternal());
85	        sortedVisits.sort(Comparator.comparing(Visit::getDate).reversed());
86	        return Collections.unmodifiableList(sortedVisits);
87	    }
88	
89	    public void setVisits(List<Visit> visits) {
90	        this.visits = new HashSet<>(visits);
91	    }
92	
93	    public void addVisit(Visit visit) {
94	        getVisitsInternal().add(visit);
95	        visit.setPet(this);
96	    }
97	
98	}
